# -*- coding: utf-8 -*-
"""Вторая волна руководств «Подготовка к олимпиаде по {предмет}» — 14 предметов с меньшим спросом.
Дописывает в src/data/olimp/prep.json (см. prep_seed.py)."""
import json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
OUT = os.path.join(ROOT, 'src', 'data', 'olimp', 'prep.json')
P = json.load(open(OUT, encoding='utf-8')) if os.path.exists(OUT) else {}

def sub(lede, sections, faq):
    return {"lede": lede, "sections": [{"h2": h, "html": x} for h, x in sections],
            "faq": [{"q": q, "a": a} for q, a in faq], "updated": "2026-09-22"}

def lang(slug, name, dat, country, exam, books):
    P[slug] = sub(
    f"Олимпиада по {dat} строится как международный экзамен уровня B1–C1: аудирование, чтение, лексико-грамматический тест, письмо и устная часть, плюс лингвострановедение — история, культура и реалии {country}. Школьного учебника мало: нужны аутентичные тексты, регулярное аудирование и знание формата.",
    [(f"Как устроена олимпиада по {dat}", f"<p>Школьный этап — с 5 класса, 60–90 минут: аудирование, чтение, лексика и грамматика. Муниципальный этап (7–11 классы) — письменный тур на 2–3 часа: аудирование, чтение, лексико-грамматический тест, письмо. Региональный и заключительный этапы (9–11 классы) — письменный тур (те же разделы плюс лингвострановедение и творческое письменное задание) и устный тур (монолог и диалог или групповая дискуссия). Уровень — от A2–B1 на школьном до B2–C1 на заключительном этапе. Критерии письма и устной части: содержание, организация, лексика, грамматика, произношение.</p>"),
     ("Какие задания встречаются", f"<ul><li><b>Аудирование</b> — интервью, репортаж или диалог: выбор ответа, «верно/неверно/не сказано», заполнение пропусков.</li><li><b>Чтение</b> — аутентичные тексты: соотнесение заголовков, восстановление абзацев, детальное понимание.</li><li><b>Лексика и грамматика</b> — cloze-тест, словообразование, трансформации, идиомы и устойчивые сочетания, времена и наклонения.</li><li><b>Лингвострановедение</b> — {country}: география, история, литература, праздники, кухня, известные люди, символы.</li><li><b>Письмо</b> — эссе, статья, письмо, рассказ: заданный объём и формат.</li><li><b>Устная часть</b> — монолог по теме с подготовкой и диалог или дискуссия с другими участниками.</li></ul>"),
     ("Темы по классам", "<ul><li><b>5–6 классы:</b> A2–B1: базовые времена, артикли, предлоги, лексика по повседневным темам, короткие тексты, простое письмо.</li><li><b>7–8 классы:</b> B1: условные предложения, косвенная речь, пассив, модальные глаголы, чтение адаптированных и аутентичных текстов, письмо-совет и рассказ, первые страноведческие вопросы.</li><li><b>9–11 классы:</b> B2–C1: сложные времена и наклонения, стилистические регистры, идиомы, эссе и статья по правилам жанра, страноведение по истории и культуре, устная дискуссия.</li></ul>"),
     ("План подготовки", f"<ol><li>Пройдите комплект прошлого года своего класса из <a href=\"/olimpiady/{slug}/\">архива</a> — с аудио, на время; разберите каждую ошибку в лексико-грамматическом тесте.</li><li>Ежедневно 20 минут аудирования на аутентичных материалах (радио, подкасты, новости) с заданиями на понимание.</li><li>Ведите тетрадь устойчивых сочетаний и идиом с примерами.</li><li>Раз в неделю — письменное задание по формату олимпиады и проверка по критериям.</li><li>Страноведение — по темам: география, история, литература, праздники, современная жизнь {country}.</li><li>За месяц — комплекты двух прошлых лет и тренировка устного монолога по таймеру.</li></ol>"),
     ("Книги, задачники и ресурсы", "<ul>" + "".join(f"<li>{b}</li>" for b in books) + f"<li>Сборники заданий ВсОШ по {dat} с аудио (ЦПМ, olimpiada.ru).</li></ul>"),
     ("Типичные ошибки", "<ul><li>Не соблюдать объём и формат письменного задания.</li><li>Не читать вопросы к аудированию заранее.</li><li>Игнорировать страноведение — это отдельный блок баллов.</li><li>Учить слова списками без контекста.</li><li>В устной части говорить заученный текст вместо ответа собеседнику.</li></ul>")],
    [("С какого класса можно участвовать?", f"Школьный этап по {dat} — с 5 класса, муниципальный — с 7, региональный и заключительный — с 9 класса."),
     ("Сколько времени нужно на подготовку?", "При уровне B1 на школьный этап — 2–3 месяца тренировки формата. Региональный этап требует B2 и года регулярной практики: аудирование каждый день, письмо раз в неделю."),
     (f"Что дают дипломы по {dat}?", f"Заключительный этап — поступление без экзаменов на лингвистику, перевод, международные отношения, филологию; вузы часто засчитывают диплом как 100 баллов ЕГЭ по {dat}. Региональный — дополнительные баллы."),
     ("Нужен ли репетитор?", f"Для письма и устной части полезен преподаватель или носитель {exam}. Аудирование, чтение и лексику тренируют самостоятельно по комплектам прошлых лет и экзаменационным пособиям.")])

